+fn part(hole: &[P2]) -> Mesh {
+    let mut f = Vec::new();
+    plate(&rect(-15.0, -15.0, 15.0, 15.0), Some((hole, 8.0)), 0.0, 20.0, &mut f);
+    Mesh::from_facets(f)
